	add(textGroup, "GET INCR DECR STRLEN", 1, 1, -1)
	add(keyGroup, "TYPE KEYS TTL PERSIST TICK", 1, 1, -1)
	add(controlGroup, "BEGIN COMMIT ROLLBACK", 0, 0, -1)
	add(controlGroup, "SNAPSHOT RESTORE", 1, 1, -1)
